// ---------------------------------------------------------------------------
// Generated catalogue extras: the curated list above stays short and
// hand-picked (it's what onboarding, the daily pick and the tests rely on),
// but "Exercices" needs real depth per category too. Each bank below is a
// list of real, specific prompts; combined with a handful of delivery
// variants (duration, extra constraint), the same pattern used for "Sujets"
// (packages/core/src/topics.ts) multiplies it into a large, still genuinely
// distinct catalogue — with stable ids, so history and best-score tracking
// keep working across reloads.

// Each bank item becomes exactly ONE exercise — no title/prompt repeated
// under different durations. A small rotating set of instructions still
// adds delivery variety across the list, but never on the same prompt
// twice, so nothing in "Exercices" ever reads as a duplicate.
const ROTATING_INSTRUCTIONS: { instruction: string; deltaSec: number; focus?: Dimension }[] = [
  { instruction: INSTR, deltaSec: 0 },
  { instruction: "Réponds en 30 secondes maximum : va droit à l'essentiel.", deltaSec: -30, focus: "concision" },
  { instruction: "Structure ta réponse en trois points annoncés dès la première phrase.", deltaSec: 15, focus: "structure" },
  { instruction: "Appuie ta réponse sur un exemple concret et si possible chiffré.", deltaSec: 0, focus: "argumentation" },
  { instruction: "Aucune préparation : enregistre-toi dès que tu as lu la question.", deltaSec: 0, focus: "confiance" },
];

function expandBank(bank: { id: string; title: string; prompt: string; focus: Dimension }[], category: CategoryId, baseDuration: number): Exercise[] {
  return bank.map((item, i) => {
    const v = ROTATING_INSTRUCTIONS[i % ROTATING_INSTRUCTIONS.length];
    return {
      id: item.id,
      category,
      title: item.title,
      prompt: item.prompt,
      instruction: v.instruction,
      durationSec: Math.max(20, baseDuration + v.deltaSec),
      focus: v.focus ?? item.focus,
    };
  });
}

