// One exercise per text — same rule as expandBank: never the same reading
// text listed twice under a different label. The instruction still rotates
// across a small set for delivery variety, but each text appears exactly once.
const PRONO_INSTRUCTIONS = [
  "Lis ce texte lentement, en articulant chaque syllabe.",
  "Lis ce texte trois fois de suite, de plus en plus vite, sans perdre en clarté.",
  "Lis ce texte en marquant une vraie pause silencieuse à chaque ponctuation.",
  "Lis ce texte en variant volontairement ton intonation : ne reste jamais monocorde.",
];

function expandProno(): Exercise[] {
  return PRONO_TEXTS.map((t, i) => ({
    id: t.id,
    category: "prononciation" as const,
    title: t.title,
    prompt: "Lis ce texte à voix haute.",
    instruction: PRONO_INSTRUCTIONS[i % PRONO_INSTRUCTIONS.length],
    durationSec: 45,
    focus: t.focus,
    readText: t.text,
  }));
}

